+/* Explain-all overview table (v55.x): one row per visible component —
+   mini chip (same box look) + its explanation. Rows click through to the
+   box (same highlight/select/narration); selected row mirrors the box. */
+.explainTable {
+  display: flex;
+  flex-direction: column;
+  gap: 6px;
+  /* max-height: 320px; */
+  /* overflow-y: auto; */
+  /* padding-right: 2px; */
+}
+
+.explainRow {
+  display: flex;
+  gap: 8px;
+  align-items: stretch;
+  /* padding: 6px 8px; */
+  background: #fff;
+  border: 1px solid var(--lightBlue);
+  border-radius: 2px;
+  cursor: pointer;
+  transition: all 0.2s;
+  outline: 0;
+}
+
+.explainRow:hover {
+  border-color: var(--vibrantGreen);
+}
+
+.explainRow.selected {
+outline: 3px solid var(--vibrantGreen);
+  outline-offset: -2px;
+  border-color: var(--vibrantGreen);
+}
+
+.explainChip {
+	flex: 0 0 auto;
+	color: #000;
+	background-color: var(--veryLightEarth);
+	border-right: 1px solid var(--lightBlue);
+	padding: 5px 6px;
+	/* border-radius: 4px; */
+	font-weight: bold;
+	white-space: nowrap;
+	/* height: 100%; */
+}
+
+/* Eye-hidden components keep their overview row: the chip mirrors the
+   hidden name box (dash on hidden fill, no pointer), the explanation cell
+   stays informative. Row clicks on hidden boxes are already inert in JS. */
+.explainRow.row-hidden {
+  cursor: default;
+}
+
+.explainRow.row-hidden:hover {
+  border-color: var(--lightBlue);
+}
+
+.explainRow.row-hidden .explainChip {
+  background-color: var(--veryLightBlue);
+  border-right-color: var(--lightBlue);
+  color: #fff;
+  min-width: 1.2em;
+  text-align: center;
+}
+
+.explainCell {
+  flex: 1 1 auto;
+  min-width: 0;
+  padding: 5px;
+}
+
+.explainCell .explainText {
+  border: 0;
+  padding: 0;
+  font-size: 0.92rem;
+}
+
 .shadow1 {
   box-shadow: 1px 1px 3px 0px rgba(0, 0, 0, 0.5);
 }
