+/* Menu collapse button — tree-lines icon at the RIGHT of the menu title.
+   Absolute (mirrored from .settingsBtn): the authoring-time scPickToggle
+   owns the left slot (absolute left:12px in the scenario CSS), the title
+   text stays centered, nothing else lives on the right. */
+.menuCollapseBtn {
+  position: absolute;
+  left: auto;
+  right: 8px;
+  top: 50%;
+  transform: translateY(-50%);
+  width: 24px;
+  height: 24px;
+  padding: 0;
+  font-size: 0.95rem;
+  line-height: 1;
+  color: var(--darkBlue);
+  background: var(--veryLightEarth);
+  border: 2px solid var(--veryLightBlue);
   border-radius: 4px;
   cursor: pointer;
-  margin-bottom: 6px;
+  z-index: 300;
+}
+
+.menuCollapseBtn:hover {
+  background: var(--darkEarth);
+  color: #fff;
+}
+
+/* Toggle language (mirrors .settingsBtn.active): expanded menu = on
+   (darkBlue), collapsed rail = off (base veryLightEarth). Driven by the
+   #menuCol state — no .active sync needed, survives menu rebuilds. */
+#menuCol:not(.collapsed) #menuCollapseBtn {
+  background: var(--darkBlue);
+  color: #fff;
+}
+
+/* Edge-anchored tooltip bubble (expanded menu): a centered one would clip
+   past the title's right edge, so anchor it right. Collapsed-rail geometry
+   is separate below (the rail sits at the viewport's left edge). */
+#menuCol:not(.collapsed) #nomeclature2Menu .panelTitle > #menuCollapseBtn[data-tooltip]::after {
+  left: auto;
+  right: 0;
+  transform: none;
+  width: max-content;
+  max-width: calc(100vw - 2rem);
+  white-space: normal;
+  overflow-wrap: anywhere;
+  line-height: 1.25;
   text-align: left;
 }

-#menuToggle:hover {
-  background-color: var(--darkBlue);
+#menuCol:not(.collapsed) #nomeclature2Menu .panelTitle > #menuCollapseBtn[data-tooltip]::before {
+  left: auto;
+  right: 12px;
+  transform: none;
+}
+
+/* Collapsible menu column: width animates rail <-> full. */
+#menuCol {
+  transition: width 0.25s ease;
+}
+
+/* Collapsed menu column: slim rail with the icon + vertical MENU text
+   (mirrors #scenarioAuthorTab: icon above, vertical-rl title below). */
+#menuCol.collapsed {
+  width: 40px;
+  min-width: 40px;
+}
+
+#menuCol.collapsed #nomeclature2Menu .panelTitle {
+  display: flex;
+  flex-direction: column;
+  align-items: center;
+  gap: 6px;
+  padding: 10px 0;
+  cursor: pointer;
+}
+
+#menuCol.collapsed #menuCollapseBtn {
+  position: relative;
+  left: auto;
+  right: auto;
+  top: auto;
+  transform: none;
+}
+
+/* Collapsed rail sits at the viewport's left edge: the expanded right-anchor
+   would spill past it, so open the bubble below + left-anchored (extends
+   right into the app, where there is room). The rail's own overflow clips
+   are lifted in the collapsed state (its scroll content is display:none
+   there, so nothing needs clipping) or the 110px bubble would be cut at
+   the 40px rail. */
+#menuCol.collapsed #menuDrawer,
+#menuCol.collapsed #nomeclature2Menu {
+  overflow: visible;
+}
+
+#menuCol.collapsed #nomeclature2Menu .panelTitle > #menuCollapseBtn[data-tooltip]::after {
+  left: 0;
+  right: auto;
+  transform: none;
+}
+
+#menuCol.collapsed #nomeclature2Menu .panelTitle > #menuCollapseBtn[data-tooltip]::before {
+  left: 12px;
+  right: auto;
+  transform: none;
+}
+
+#menuCol.collapsed .menuTitleText {
+  display: block;
+  writing-mode: vertical-rl;
+  font-weight: 600;
+  letter-spacing: 0.06em;
+  line-height: 1.2;
+}
+
+#menuCol.collapsed #nomeclature2Menu .groupingMode,
+#menuCol.collapsed #nomeclature2Menu .menuNomeclature2Container,
+#menuCol.collapsed #nomeclature2Menu .panelTitle #scPickToggle {
+  display: none;
+}
+
+/* Collapsed menu frees 190px, split viewer +80 / naming +110 (naming
+   weighted — long names scale up into the width): row total is conserved,
+   so nothing recenters. Animates with the rail. */
+#menuCol.collapsed ~ #viewerCol {
+  max-width: 700px;
+}
+
+#menuCol.collapsed ~ #analysisCol {
+  width: 460px;
+}
+
+#viewerCol {
+  transition: max-width 0.25s ease;
+}
+
+#analysisCol {
+  transition: width 0.25s ease;
+}
+
+@media (prefers-reduced-motion: reduce) {
+  #menuCol,
+  #viewerCol,
+  #analysisCol {
+    transition: none;
+  }
 }

