+.scenarioDrawer .srow:not(.collapsed) .srowBody {
+   overflow: visible;
+}
+
+@media (prefers-reduced-motion: reduce) {
+
+   .scenarioDrawer .srow .srowBody,
+   .scenarioDrawer .srow.collapsed .srowBody {
