+<!doctype html>
+<html lang="en">
+<head>
+  <meta charset="UTF-8" />
+  <title>core/molview 56 chemistry regression</title>
+</head>
+<body>
+  <!--
+    Headless regression for the v56 naming engine (docs/REVIEW-CORE-MOLVIEW-56.md).
+    Loads the real app in an iframe (needs an http server: python -m http.server),
+    names every stored molecule through fSelectMol and a set of drawn probes
+    through the draft path (fAnalyseStructure/fDetectMolType/fGuessName), then
+    prints JSON into #out and sets document.title to CORE56-DONE.
+    Usage: serve the repo root (python -m http.server 8099), then open
+           zz-test-core56.html  -> JSON in #out, title "CORE56-DONE PASS|FAIL"
+           chrome --headless=new --virtual-time-budget=180000 --dump-dom http://localhost:8099/zz-test-core56.html
+    Also records fParseSDF3D/fDetectMolType3D/fCalcMainChain3D for all stored
+    molecules (res.threeD) so 2D/3D drift can be diffed between revisions.
+  -->
+  <iframe id="app" src="mulermoc-nom-56.html?libs=local" style="width:1200px;height:900px"></iframe>
+  <pre id="out">booting…</pre>
+  <script>
+    (function () {
+      var frame = document.getElementById("app");
+      var out = document.getElementById("out");
+      // [label, SMILES, expected EN name | "DECLINE"]. Declines are deliberate
+      // (fail-closed): unsupported groups must never fall back to a skeleton name.
+      var probes = [
+        ["dodeca_2_10_diene", "CC=CCCCCCCC=CC", "dodeca-2,10-diene"],
+        ["chloroethanol", "ClCCO", "2-chloroethanol"],
+        ["bromo_hydroxy_ketone", "BrCC(=O)CCO", "1-bromo-4-hydroxybutan-2-one"],
+        ["hydroxypentanone", "OCCCC(=O)C", "5-hydroxypentan-2-one"],
+        ["pentanone_5_hydroxy_rev", "CC(=O)CCCO", "5-hydroxypentan-2-one"],
+        ["hydroxypentanone_4", "CC(O)CC(=O)C", "4-hydroxypentan-2-one"],
+        ["dinitropropane", "O=[N+]([O-])CCC[N+](=O)[O-]", "1,3-dinitropropane"],
+        ["tri_nitro_geminal", "O=[N+]([O-])C(CC)[N+](=O)[O-]", "1,1-dinitropropane"],
+        ["nitropropane_pentavalent", "O=N(=O)CCC", "1-nitropropane"],
+        ["nitroethanol_N_first", "[N+](=O)([O-])CCO", "2-nitroethanol"],
+        ["nitroso", "CCCN=O", "DECLINE"],
+        ["propanamine_1", "CCCN", "DECLINE"],
+        ["propanamine_2", "CC(N)C", "DECLINE"],
+        ["ethylenediamine", "NCCN", "DECLINE"],
+        ["nitroamine", "NCC[N+](=O)[O-]", "DECLINE"],
+        ["dimethylamine", "CNC", "DECLINE"],
+        ["thiol", "CCS", "DECLINE"],
+        ["methoxyethanol", "COCCO", "DECLINE"],
+        ["imine", "CCC=N", "DECLINE"],
+        ["ester_acid", "COC(=O)CCC(=O)O", "DECLINE"],
+        ["hydroxy_acid_ok", "CC(O)C(=O)O", "2-hydroxypropanoic acid"],
+        ["oxo_acid_ok", "O=CC(=O)O", "2-oxoethanoic acid"],
+        ["butenedioic_acid_ok", "OC(=O)C=CC(=O)O", "but-2-enedioic acid"],
+        ["chlorobutane_ok", "CCCCCl", "1-chlorobutane"],
+        ["methoxyethane_ok", "CCOC", "methoxyethane"],
+        ["methylundecadiene_ok", "CC=CCC(C)CCCC=CC", "5-methylundeca-2,9-diene"],
+        ["chloropropanol", "OCC(Cl)C", "2-chloropropan-1-ol"],
+        ["bromo_chloro_propanol", "OCC(Br)CCl", "2-bromo-3-chloropropan-1-ol"],
+        ["dichloro_ketone", "ClCC(=O)CCCCl", "1,5-dichloropentan-2-one"],
+        ["serine_like", "OCC(N)C(=O)O", "2-amino-3-hydroxypropanoic acid"],
+        ["hydroxy_acid_c11", "OC(=O)C(O)CCCCCCCCC", "2-hydroxyundecanoic acid"]
+      ];
+      function parse(s) {
+        var atoms = [], bonds = [], stack = [], prev = -1, order = 1, i = 0;
+        while (i < s.length) {
+          var c = s[i], el;
+          if (c === "(") { stack.push(prev); i++; continue; }
+          if (c === ")") { prev = stack.pop(); i++; continue; }
+          if (c === "=") { order = 2; i++; continue; }
+          if (c === "#") { order = 3; i++; continue; }
+          if (c === "[") { var j = s.indexOf("]", i); el = /[A-Z][a-z]?/.exec(s.slice(i + 1, j))[0]; i = j + 1; }
+          else if (s.substr(i, 2) === "Cl" || s.substr(i, 2) === "Br") { el = s.substr(i, 2); i += 2; }
+          else { el = c; i++; }
+          atoms.push(el);
+          var idx = atoms.length - 1;
+          if (prev >= 0) bonds.push([prev, idx, order]);
+          prev = idx; order = 1;
+        }
+        return { atoms: atoms, bonds: bonds };
+      }
+      function pad(s, n) { s = String(s); while (s.length < n) s = " " + s; return s; }
+      function molText(name, smi) {
+        var p = parse(smi), n = p.atoms.length, depth = new Array(n).fill(-1);
+        depth[0] = 0;
+        var q = [0];
+        while (q.length) {
+          var a = q.shift();
+          p.bonds.forEach(function (b) {
+            var o = b[0] === a ? b[1] : (b[1] === a ? b[0] : -1);
+            if (o >= 0 && depth[o] < 0) { depth[o] = depth[a] + 1; q.push(o); }
+          });
+        }
